local function jointKey(query)
    if not query.family or query.family == "" or not query.compWatch or query.compWatch == ""
        or not query.scoreState or query.scoreState == "" or not query.counterResponse or query.counterResponse == ""
        or not query.evidenceState or query.evidenceState == "" then return nil end
    local values = { query.family, query.compWatch, query.scoreState, query.counterResponse, query.evidenceState }
    return table.concat(values, "\31")
end

function StrategistNexusCorpus:Count() return DATA.totalCases end
function StrategistNexusCorpus:Status() return DATA.sourceStatus end
function StrategistNexusCorpus:Activation() return DATA.activation end
function StrategistNexusCorpus:Patch() return DATA.patch end
function StrategistNexusCorpus:Map(mapKey) return DATA.maps[mapKey] end

function StrategistNexusCorpus:Coverage(mapKey, phase, query)
    local map = DATA.maps[mapKey]
    local bucket = map and map.phases and map.phases[phase]
    if not bucket then
        return { available = false, marginalCases = 0, sourceStatus = DATA.sourceStatus }
    end
    query = type(query) == "table" and query or {}
    local key = jointKey(query)
    local hasQuery = next(query) ~= nil
    -- An incomplete filter cannot be treated as exact support. Empty
    -- queries intentionally report phase coverage; filtered queries
    -- require every indexed dimension and otherwise fail closed.
    local exactKnown = key and bucket.families[query.family] and bucket.compWatches[query.compWatch]
        and bucket.scoreStates[query.scoreState] and bucket.counterResponses[query.counterResponse]
        and bucket.evidenceStates[query.evidenceState]
    local count = not hasQuery and bucket.totalCases
        or (bucket.completeMatrix and exactKnown and 1)
        or (key and (bucket.jointCases and bucket.jointCases[key] or 0) or 0)
    return {
        available = count > 0,
        marginalCases = count,
        exactCases = count,
        phaseCases = bucket.totalCases,
        mapCases = map.totalCases,
        totalCases = DATA.totalCases,
        sourceStatus = DATA.sourceStatus,
        patch = DATA.patch,
        mapProfile = map.mapProfile,
    }
end

function StrategistNexusCorpus:Shared() return DATA end

KWR:RegisterModule("StrategistNexusCorpus", StrategistNexusCorpus)
